import heapq

def match(orders):
    trades = []
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}       # id -> dict with side, price, qty, seq, active
    seq_counter = 0

    def clean_buy():
        while buy_heap:
            negp, s, oid = buy_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            break

    def clean_sell():
        while sell_heap:
            p, s, oid = sell_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            break

    def match_incoming(side, price, qty, incoming_id, is_limit):
        nonlocal trades
        remaining = qty
        if side == 'buy':
            # match against sell_heap, lowest price first
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                p, s, oid = sell_heap[0]
                if price is not None and p > price:
                    break
                o = book[oid]
                trade_qty = min(remaining, o['qty'])
                trades.append([incoming_id, oid, p, trade_qty])
                remaining -= trade_qty
                o['qty'] -= trade_qty
                if o['qty'] <= 0:
                    o['active'] = False
                    heapq.heappop(sell_heap)
                # else keep at front, will be matched more if remaining>0, next loop same top since qty leftover
        else:
            # side == 'sell', match against buy_heap, highest price first
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negp, s, oid = buy_heap[0]
                p = -negp
                if price is not None and p < price:
                    break
                o = book[oid]
                trade_qty = min(remaining, o['qty'])
                trades.append([oid, incoming_id, p, trade_qty])
                remaining -= trade_qty
                o['qty'] -= trade_qty
                if o['qty'] <= 0:
                    o['active'] = False
                    heapq.heappop(buy_heap)
        return remaining

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o is not None and o['active']:
                o['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, oid, True)
            if remaining > 0:
                seq_counter += 1
                o = {'side': side, 'price': price, 'qty': remaining, 'seq': seq_counter, 'active': True}
                book[oid] = o
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq_counter, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq_counter, oid))
            else:
                # fully filled, still register as inactive/filled entry for cancel-no-op safety
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': -1, 'active': False}

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, oid, False)
            book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': -1, 'active': False}

        elif typ == 'market':
            _, oid, side, qty = order
            remaining = match_incoming(side, None, qty, oid, False)
            book[oid] = {'side': side, 'price': None, 'qty': 0, 'seq': -1, 'active': False}

    return trades

